"""Generates crates/af-cli/src/menu.rs from src/ui/MenuParity.cpp (where each
pipeline step appears in the desktop menus). Run from the repository root:
python rust/tools/gen_cli_menu.py"""
import re

source = open("src/ui/MenuParity.cpp", encoding="utf-8").read()
rows = re.findall(r'\{"([^"]*)", "([^"]*)", "([^"]*)", "([^"]*)", (true|false)\}', source)
out = [
    "//! Where every structure-pipeline step appears in the desktop menus (the",
    "//! C++ ui/MenuParity), generated by rust/tools/gen_cli_menu.py.",
    "",
    "/// (step, menu, submenu, label, has a dedicated dialog).",
    "pub const MENU_LOCATIONS: &[(&str, &str, &str, &str, bool)] = &[",
]
for step, menu, submenu, label, dialog in rows:
    out.append('    ("%s", "%s", "%s", "%s", %s),' % (step, menu, submenu, label, dialog))
out += [
    "];",
    "",
    "/// \"Build > Vacancies\", or empty when a step has no menu location.",
    "pub fn menu_path_of(step: &str) -> String {",
    "    for &(id, menu, submenu, label, _) in MENU_LOCATIONS {",
    "        if id == step {",
    "            return if submenu.is_empty() { format!(\"{menu} > {label}\") } else { format!(\"{menu} > {submenu} > {label}\") };",
    "        }",
    "    }",
    "    String::new()",
    "}",
    "",
]
with open("rust/crates/af-cli/src/menu.rs", "w", newline="\n", encoding="utf-8") as f:
    f.write("\n".join(out))
print(len(rows), "menu locations")
